(function(){
  "use strict";

  function clamp(v, lo, hi){ return Math.max(lo, Math.min(hi, v)); }

  function normalizeAngle(deg){
    let a = ((deg % 360) + 360) % 360;
    const snap = Math.round(a / 90) * 90;
    return ((snap % 360) + 360) % 360;
  }

  function formatBytes(n){
    if (!isFinite(n) || n < 0) return "0 B";
    const u = ["B","KB","MB","GB"]; let i = 0;
    while (n >= 1024 && i < u.length - 1){ n /= 1024; i++; }
    return (i === 0 ? String(n) : n.toFixed(1)) + " " + u[i];
  }

  // 解析 "1,3,5-8" 形式页码规格（1 起），返回排序去重后的 0 起索引
  function parsePageSpec(spec, total){
    if (total == null || total < 1) return [];
    if (!spec || !String(spec).trim()) return [];
    const out = [];
    const seen = {};
    const parts = String(spec).split(",");
    for (const raw of parts){
      const p = String(raw).trim();
      if (!p) continue;
      if (p.indexOf("-") >= 0){
        const seg = p.split("-");
        const a = parseInt(seg[0], 10), b = parseInt(seg[1], 10);
        if (isNaN(a) || isNaN(b)) continue;
        const lo = clamp(Math.min(a, b), 1, total);
        const hi = clamp(Math.max(a, b), 1, total);
        for (let i = lo; i <= hi; i++){ if (!seen[i]){ seen[i] = 1; out.push(i - 1); } }
      } else {
        const v = parseInt(p, 10);
        if (isNaN(v)) continue;
        if (v >= 1 && v <= total && !seen[v]){ seen[v] = 1; out.push(v - 1); }
      }
    }
    return out.sort(function(x, y){ return x - y; });
  }

  // 校验 PDF 文件（名称 + 大小）
  function validatePdf(name, size){
    if (!name || typeof name !== "string") return { ok:false, error:"文件名缺失" };
    if (!/\.pdf$/i.test(name)) return { ok:false, error:"请选择 .pdf 文件" };
    if (!size || size <= 0) return { ok:false, error:"文件为空" };
    return { ok:true, error:"" };
  }

  // 给定每页当前角度数组与增量，返回新角度数组（归一化到 0/90/180/270）
  function planRotate(angles, delta){
    return (angles || []).map(function(a){ return normalizeAngle((a || 0) + delta); });
  }

  // 排序去重
  function dedupeSorted(arr){
    const out = []; let prev = null;
    arr.slice().sort(function(a, b){ return a - b; }).forEach(function(x){
      if (x !== prev){ out.push(x); prev = x; }
    });
    return out;
  }

  // 解析重排规格 "3,1,2,4" -> 0 起索引数组（越界/非数字忽略），保持输入顺序
  function parseOrderSpec(spec, total){
    if (!spec || !String(spec).trim()) return [];
    const idx = [];
    String(spec).split(",").forEach(function(raw){
      const p = String(raw).trim();
      if (!p) return;
      const v = parseInt(p, 10);
      if (isNaN(v) || v < 1 || v > total) return;
      idx.push(v - 1);
    });
    return idx;
  }

  const API = {
    clamp: clamp, normalizeAngle: normalizeAngle, formatBytes: formatBytes,
    parsePageSpec: parsePageSpec, validatePdf: validatePdf,
    planRotate: planRotate, dedupeSorted: dedupeSorted, parseOrderSpec: parseOrderSpec
  };

  if (typeof module !== "undefined" && module.exports){ module.exports = API; }
  if (typeof window !== "undefined"){ window.PDFPure = API; }
})();
